DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.contract_commit_signature(uuid,uuid,uuid,text,text,text,text,text,text,text,jsonb,timestamptz)'::regprocedure) INTO d; d:=replace(d,'contractor_artifacts(applicant_id,kind,storage_path,filename)','contractor_artifacts(applicant_id,kind,storage_path,file_name)'); EXECUTE d; END $$;
CREATE OR REPLACE FUNCTION public.signing_equipment_sync() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.applicants SET equipment_approved=NEW.proof_approved_at IS NOT NULL WHERE id=NEW.applicant_id AND equipment_approved IS DISTINCT FROM (NEW.proof_approved_at IS NOT NULL); RETURN NEW; END $$;
CREATE TRIGGER signing_equipment_sync AFTER UPDATE OF proof_approved_at ON public.contractor_pipeline FOR EACH ROW EXECUTE FUNCTION public.signing_equipment_sync();